const examples=[{id:'demo-01',title:'Применение RAG для поиска по научным публикациям',author:'Демонстрационный автор А.',year:2024,page:12,excerpt:'Вымышленный фрагмент: рассматривается извлечение релевантных материалов перед генерацией ответа.'},{id:'demo-02',title:'Поисковые методы в университетских цифровых архивах',author:'Демонстрационный автор Б.',year:2024,page:8,excerpt:'Вымышленный фрагмент: сравниваются лексические подходы к ранжированию документов.'},{id:'demo-03',title:'Системы вопросно-ответного поиска по документам',author:'Демонстрационный автор В.',year:2024,page:21,excerpt:'Вымышленный фрагмент: приводится пример ответа со ссылкой на исходный текст.'}];
const $=id=>document.getElementById(id);
$('searchForm').addEventListener('submit',e=>{e.preventDefault();const q=$('query').value.trim(),year=$('year').value;if(!q)return;$('result').classList.remove('hidden');$('sources').replaceChildren();if(year&&year!=='2024'){$('answer').textContent='В демонстрационном наборе нет работ за '+year+' год. Это не результат настоящего поиска.';return;}$('answer').textContent='Демонстрационный ответ на вопрос «'+q+'»: в условном архиве есть примеры исследований о RAG, поиске и вопросно-ответных системах. Для реальных выводов необходимо подключить корпус PDF, собственный BM25 и LLM.';examples.forEach((s,i)=>{const d=document.createElement('div');d.className='source';const info=document.createElement('div');const name=document.createElement('strong');name.textContent=(i+1)+'. '+s.title;const meta=document.createElement('span');meta.className='muted';meta.textContent=s.author+' · '+s.year+' · стр. '+s.page;info.append(name,meta);const b=document.createElement('button');b.className='btn ghost';b.textContent='Фрагмент';b.addEventListener('click',()=>{$('dialogTitle').textContent=s.title;$('dialogMeta').textContent=s.author+' · '+s.year+' · стр. '+s.page+' · ID: '+s.id;$('dialogExcerpt').textContent=s.excerpt;$('sourceDialog').showModal()});d.append(info,b);$('sources').append(d)});});
$('closeDialog').addEventListener('click',()=>$('sourceDialog').close());
$('upload').addEventListener('click',()=>{const file=$('pdf').files[0];if(!file){$('uploadStatus').textContent='Сначала выберите PDF.';return}if(!file.name.toLowerCase().endsWith('.pdf')){$('uploadStatus').textContent='Нужен PDF-файл.';return}if(!$('permission').checked){$('uploadStatus').textContent='Подтвердите право на размещение.';return}$('uploadStatus').textContent='Демо: «'+file.name+'» выбран. Файл никуда не отправлен и не сохранён.'});
